        let (status, payload) = ExecShell
            .execute(&ctx, json!({ "command": "echo hello from mia" }))
            .await;
        assert_eq!(status, ToolStatus::Success);
        assert_eq!(payload["exit_code"], 0);
        assert!(payload["stdout"].as_str().unwrap().contains("hello from mia"));
